  "system.auto.nywtw1.95": "Each approved package is immutable, tenant-owned, and applied only after you choose a document.",
  "system.auto.1odr0s.177": "Each cohort starts immediately and lasts 30 days. Reserve at least one seat for an independent reviewer. Use only non-sensitive source material your team is licensed to provide.",
  "system.auto.1ojvk5d.271": "Each image is run through both local implementations. The current method preserves aspect ratio and selects a coherent attention region; the baseline reproduces the original square-sample saliency centroid. These calculations are intentionally not appended to a document.",
